    longDescEs: "La Universidad de Ginebra otorga becas de excelencia a los mejores estudiantes internacionales para cursar maestrías en su campus. Ginebra es única en el mundo: es sede de la ONU Europa, la OMS, el CICR, la OMC y decenas de organismos internacionales — lo que abre oportunidades de networking sin igual para quienes estudian relaciones internacionales, salud pública, derecho internacional o ciencias. La beca cubre entre CHF 1,000–1,500 mensuales. Requiere excelencia académica demostrada y dominio del idioma del programa (francés o inglés).",
    longDescEn: "The University of Geneva grants excellence fellowships to top international students to pursue master's degrees on its campus. Geneva is unique in the world: it hosts the UN Europe, WHO, ICRC, WTO, and dozens of international organizations — opening unparalleled networking opportunities for those studying international relations, public health, international law, or sciences. The fellowship covers CHF 1,000–1,500 per month. Requires demonstrated academic excellence and proficiency in the program language (French or English).",
