    longDescEs: "El Programa de Becas JJ/WBGSP del Banco Mundial está dirigido a ciudadanos de países en desarrollo (como Perú) con talento excepcional, historial de liderazgo y compromiso con el retorno a su país para contribuir a su desarrollo. Cubre matrícula completa, estipendio de manutención, pasaje aéreo y seguro médico para maestrías en universidades reconocidas de todo el mundo. Los temas prioritarios incluyen economía del desarrollo, salud pública, políticas sociales, gestión pública y medio ambiente. Los becarios forman parte de una red global de agentes de cambio.",
    longDescEn: "The JJ/WBGSP World Bank Scholarship Programme targets citizens of developing countries (like Peru) with exceptional talent, leadership record, and commitment to returning to their country to contribute to its development. It covers full tuition, living stipend, airfare, and health insurance for master's degrees at recognized universities worldwide. Priority topics include development economics, public health, social policy, public administration, and environment. Scholars join a global network of change agents.",
