    orgEn: "Real Sociedad Matemática Española / OIM Organization",
    descEs: "Olimpiada de matemáticas para jóvenes de Iberoamérica — uno de los principales escalones hacia la IMO (Olimpiada Internacional de Matemática).",
    descEn: "Mathematics olympiad for Iberoamerican youth — one of the main stepping stones toward the IMO (International Mathematical Olympiad).",
    longDescEs: "La Olimpiada Iberoamericana de Matemática (OIM) es una competencia regional anual que reúne a los mejores estudiantes de matemáticas de España, Portugal y toda Latinoamérica. Se realiza en septiembre en un país diferente cada año. Los participantes son seleccionados por la Olimpiada Nacional de cada país — en Perú, la ONMATH y la ONEM son las vías de clasificación. La OIM es un paso clave para los jóvenes que quieren llegar a la IMO, la olympiada internacional máxima. La participación es gratuita para los seleccionados y todos los gastos del viaje son cubiertos.",
    longDescEn: "The Iberoamerican Mathematical Olympiad (OIM) is an annual regional competition bringing together the best mathematics students from Spain, Portugal, and all of Latin America. It takes place in September in a different country each year. Participants are selected through each country's National Olympiad — in Peru, ONMATH and ONEM are the qualification pathways. OIM is a key step for young people who want to reach IMO, the maximum international olympiad. Participation is free for the selected students and all travel expenses are covered.",
